use oh_my_3do_library::model::{Preferences,LibraryView};
#[test]
fn library_views_round_trip_independently_and_previous_preferences_default_to_no_selections(){let old:Preferences=serde_json::from_str(r#"{"library":"D:/3DO","offline":true}"#).unwrap();assert!(old.library_views.is_empty());assert!(old.offline);let mut prefs=old;prefs.library_views.insert("D:/3DO".into(),LibraryView{selected:vec!["Games/USA/Doom".into()],search:"doom".into(),category:"Games".into(),region:"USA".into()});prefs.library_views.insert("E:/Small".into(),LibraryView::default());let restored:Preferences=serde_json::from_slice(&serde_json::to_vec(&prefs).unwrap()).unwrap();assert_eq!(restored.library_views["D:/3DO"].selected,vec!["Games/USA/Doom"]);assert!(restored.library_views["E:/Small"].selected.is_empty());assert_eq!(restored.library_views["D:/3DO"].search,"doom");}
